const RenderLayerPaths: React.FC<{
  paths: { cream?: string; teal?: string; crimson?: string };
}> = ({ paths }) => (
  <>
    {paths.cream && (
      <path
        d={paths.cream}
        fill="#F5F2EB"
        stroke="#F5F2EB"
        strokeWidth="0.5"
        strokeLinejoin="round"
        fillRule="evenodd"
      />
    )}
    {paths.teal && (
      <path
        d={paths.teal}
        fill="#17B8B8"
        stroke="#17B8B8"
        strokeWidth="0.5"
        strokeLinejoin="round"
        fillRule="evenodd"
      />
    )}
    {paths.crimson && (
      <path
        d={paths.crimson}
        fill="#E6194B"
        stroke="#E6194B"
        strokeWidth="0.5"
        strokeLinejoin="round"
        fillRule="evenodd"
      />
    )}
  </>
);

export const CazeAnimatedSvg: React.FC<{
  gameId: string;
  className?: string;
  preserveAspectRatio?: string;
}> = ({ gameId, className = '', preserveAspectRatio }) => {
  const vec = CAZE_VECTOR_DATA[gameId];
  if (!vec) return null;

  const defaultPAR =
    preserveAspectRatio ||
    (gameId === 'tem-ou-nao-tem' ? 'xMidYMid meet' : 'xMidYMax meet');

  return (
    <svg
      viewBox={vec.viewBox}
      preserveAspectRatio={defaultPAR}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`rdb-caze-svg ${className}`}
      aria-hidden="true"
    >
      {/* Base Cartoon Layer */}
      <g className="rdb-svg-base">
        <RenderLayerPaths paths={vec.base} />
      </g>

      {/* Secondary Hover-Animated Layer (Hands / Bars / Cards / Score) */}
      <g
        className={vec.anim2.className}
        style={{ transformOrigin: vec.anim2.origin }}
      >
        <RenderLayerPaths paths={vec.anim2.paths} />
      </g>

      {/* Primary Hover-Animated Layer (Bubble / Siren / Stars / Sweat / Bells) */}
      <g
        transform={vec.anim1.translateY ? `translate(0, ${vec.anim1.translateY})` : undefined}
      >
        <g
          className={vec.anim1.className}
          style={{ transformOrigin: vec.anim1.origin }}
        >
          <RenderLayerPaths paths={vec.anim1.paths} />
        </g>
      </g>

      {/* Optional Crimson Danger Gauge Pulse Overlay (Jogo do Limite) */}
      {vec.extraCrimsonOverlay && (
        <g
          className={vec.extraCrimsonOverlay.className}
          style={{ transformOrigin: vec.extraCrimsonOverlay.origin }}
        >
          <path
            d={vec.extraCrimsonOverlay.d}
            fill="#E6194B"
            fillRule="evenodd"
          />
        </g>
      )}
    </svg>
  );
};
